      ),
    )
    .run();
}

/**
 * Drops the issue and comment documents of every archived issue in a project.
 * Covers the cascade in `archiveProject`, which archives issues without
 * emitting `issue.archived` for each one.
 */
export async function deleteArchivedIssueDocuments(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const db = getDb();
  const archivedIssues = db
    .select({ id: issues.id })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        isNotNull(issues.archivedAt),
      ),
    );
  const archivedIssueComments = db
    .select({ id: comments.id })
    .from(comments)
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        inArray(comments.issueId, archivedIssues),
      ),
    );

  db.delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        or(
          and(
            eq(searchIndex.subjectKind, "issue"),
            inArray(searchIndex.subjectId, archivedIssues),
          ),
          and(
            eq(searchIndex.subjectKind, "comment"),
            inArray(searchIndex.subjectId, archivedIssueComments),
          ),
        ),
      ),
    )
    .run();
}

