import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("./_support/doubles/misc")).rateLimitModule);

import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as searchRepo from "@/server/repositories/search-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

const q = (orgId: string, term: string, kinds: ("issue" | "comment" | "project")[] = ["comment"]) => ({
  orgId: orgId as never,
  q: term,
  kinds,
  limit: 100,
  cursor: null,
});

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  tenant = await createTenant("tmpscen", "growth");
});

afterAll(() => {
  detach();
  cleanup();
});

describe("scenarios", () => {
  it("1+2: deleting a comment removes only it; reply and issue stay", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "ScenIssueA" }),
    );
    const parent = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id, issueId: issue.id, body: "ParentAlpha", parentId: null, mentionedUserIds: [],
    });
    const reply = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id, issueId: issue.id, body: "ReplyBravo", parentId: parent.id, mentionedUserIds: [],
    });
    expect(await commentRepo.countComments(tenant.org.id, issue.id)).toBe(2);

    await commentService.deleteComment(tenant.actors.member, { orgId: tenant.org.id, commentId: parent.id });

    expect((await searchService.search(tenant.actors.member, q(tenant.org.id, "ParentAlpha"))).total).toBe(0);
    expect((await searchService.search(tenant.actors.member, q(tenant.org.id, "ReplyBravo"))).total).toBe(1);
    expect((await searchService.search(tenant.actors.member, q(tenant.org.id, "ScenIssueA", ["issue"]))).total).toBe(1);
    expect(await commentRepo.countComments(tenant.org.id, issue.id)).toBe(1);
    expect(reply.id).toBeDefined();
  });

  it("3: archiving an issue removes its comments and replies, not other issues'", async () => {
    const a = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "ScenIssueB" }),
    );
    const b = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "ScenIssueC" }),
    );
    const top = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id, issueId: a.id, body: "CharlieTop", parentId: null, mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id, issueId: a.id, body: "DeltaReply", parentId: top.id, mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id, issueId: b.id, body: "EchoOther", parentId: null, mentionedUserIds: [],
    });

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, a.id);

    expect((await searchService.search(tenant.actors.member, q(tenant.org.id, "CharlieTop"))).total).toBe(0);
    expect((await searchService.search(tenant.actors.member, q(tenant.org.id, "DeltaReply"))).total).toBe(0);
    expect((await searchService.search(tenant.actors.member, q(tenant.org.id, "EchoOther"))).total).toBe(1);
  });

  it("4+5: rebuild indexes exactly live content, is idempotent, and walks every page", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "ScenIssueD" }),
    );
    const gone = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id, issueId: issue.id, body: "FoxtrotGone", parentId: null, mentionedUserIds: [],
    });
    const parentGone = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id, issueId: issue.id, body: "GolfParentGone", parentId: null, mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id, issueId: issue.id, body: "HotelLiveReply", parentId: parentGone.id, mentionedUserIds: [],
    });
    await commentService.deleteComment(tenant.actors.member, { orgId: tenant.org.id, commentId: gone.id });
    await commentService.deleteComment(tenant.actors.member, { orgId: tenant.org.id, commentId: parentGone.id });

    // Simulate stale docs left behind by an old index.
    await searchRepo.upsertSearchDocument(tenant.org.id, "comment", gone.id, "FoxtrotGone", null);
    const archivedIssue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "ScenIssueE" }),
    );
    await searchRepo.upsertSearchDocument(tenant.org.id, "issue", archivedIssue.id, "ScenIssueE", tenant.project.id);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedIssue.id);
    await searchRepo.upsertSearchDocument(tenant.org.id, "issue", archivedIssue.id, "ScenIssueE", tenant.project.id);

    // A bulk backlog: more than one page of comments on one issue.
    const big = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "ScenBigIssue" }),
    );
    for (let i = 0; i < 230; i += 1) {
      await commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id, issueId: big.id, body: `BulkComment${i}`, parentId: null, mentionedUserIds: [],
      });
    }

    await runSearchReindexJob(tenant.org.id);
    const afterFirst = await searchRepo.countIndexed(tenant.org.id);
    await runSearchReindexJob(tenant.org.id);
    const afterSecond = await searchRepo.countIndexed(tenant.org.id);
    expect(afterSecond).toBe(afterFirst);

    expect((await searchService.search(tenant.actors.member, q(tenant.org.id, "FoxtrotGone"))).total).toBe(0);
    expect((await searchService.search(tenant.actors.member, q(tenant.org.id, "GolfParentGone"))).total).toBe(0);
    expect((await searchService.search(tenant.actors.member, q(tenant.org.id, "HotelLiveReply"))).total).toBe(1);
    expect((await searchService.search(tenant.actors.member, q(tenant.org.id, "ScenIssueE", ["issue"]))).total).toBe(0);
    expect((await searchService.search(tenant.actors.member, q(tenant.org.id, "ScenIssueD", ["issue"]))).total).toBe(1);
    expect((await searchService.search(tenant.actors.member, q(tenant.org.id, "BulkComment0"))).total).toBe(1);
    expect((await searchService.search(tenant.actors.member, q(tenant.org.id, "BulkComment229"))).total).toBe(1);
  });

  it("5b: rebuild covers more than one page of issues, including the oldest", async () => {
    const first = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "OldestIssueZulu" }),
    );
    for (let i = 0; i < 120; i += 1) {
      await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: `Filler${i}` }),
      );
    }
    await searchRepo.deleteSearchDocumentsForOrg(tenant.org.id);
    await runSearchReindexJob(tenant.org.id);
    expect((await searchService.search(tenant.actors.member, q(tenant.org.id, "OldestIssueZulu", ["issue"]))).total).toBe(1);
    expect(first.id).toBeDefined();
  });

  it("archiving a project with its issues removes their documents", async () => {
    const p = await projectService.createProject(tenant.actors.owner ?? tenant.actors.member, {
      orgId: tenant.org.id, name: "ScenProj", slug: "scen-proj", key: "SCN", description: null,
    } as never).catch(() => null);
    if (!p) return;
    const i = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, p.id, { title: "ProjCascadeTango" }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id, issueId: i.id, body: "ProjCascadeUniform", parentId: null, mentionedUserIds: [],
    });
    await projectService.archiveProject(tenant.actors.owner ?? tenant.actors.member, {
      orgId: tenant.org.id, projectId: p.id, archiveIssues: true,
    } as never);
    expect((await searchService.search(tenant.actors.member, q(tenant.org.id, "ProjCascadeTango", ["issue"]))).total).toBe(0);
    expect((await searchService.search(tenant.actors.member, q(tenant.org.id, "ProjCascadeUniform"))).total).toBe(0);
  });
});

